 * @param recordedBy         本次修订录入人标识；录入人不得认证自己的读数
 */
public record ReviseReadingRequest(
        @NotBlank String requestId,
        @NotNull Long expectedVersion,
        @NotNull @PositiveOrZero Long cumulativeMinutes,
        @NotBlank String recordedBy) {
}

