    @Test
    void certifyBatch_regressionAgainstCertified_rollsBack() throws Exception {
        // 已认证序列 10:00=100、11:00=200；中间补录 12:00=150 不可能（录入期拦截），
        // 但已认证读数可沿修订链创建新版本（值变小）后重新认证，此时最终序列倒退 → 整批回滚。
        register("eq-rg", 1000);
        addReading("eq-rg", "rg-a1", 1, "r1", "2026-01-01T10:00:00Z", 100, "alice");
        addReading("eq-rg", "rg-a2", 2, "r2", "2026-01-01T11:00:00Z", 200, "alice");
        certify("ck-rg-1", "bob",
                        "[" + item("eq-rg", "r1", 1) + "," + item("eq-rg", "r2", 1) + "]")
                .andExpect(status().isCreated());
        mockMvc.perform(get("/api/equipment/eq-rg/status"))
                .andExpect(jsonPath("$.latestCumulativeMinutes").value(200))
                .andExpect(jsonPath("$.version").value(4));

        // 已认证读数不可直接修改：沿修订链创建新版本（r2 修订为 150），新版本回到 PENDING
        mockMvc.perform(post("/api/equipment/eq-rg/readings/r2/revisions")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"requestId":"rg-rev","expectedVersion":4,"cumulativeMinutes":150,"recordedBy":"alice"}
                                """))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.revisionNo").value(2))
                .andExpect(jsonPath("$.certStatus").value("PENDING"));

        // 修订后 PENDING 不参与判定：最新已认证回退到 r1=100
        mockMvc.perform(get("/api/equipment/eq-rg/status"))
                .andExpect(jsonPath("$.latestCumulativeMinutes").value(100));

        // 旧版本（revisionNo=1）已不可认证 → 422 版本不一致
        certify("ck-rg-2", "bob", "[" + item("eq-rg", "r2", 1) + "]")
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.code").value("READING_VERSION_CONFLICT"));

        // 重新认证新版本 r2=150：与已认证 r1=100 单调 → 成功
        certify("ck-rg-3", "bob", "[" + item("eq-rg", "r2", 2) + "]")
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.results[0].latestCumulativeMinutes").value(150));
        mockMvc.perform(get("/api/equipment/eq-rg/certifications"))
                .andExpect(jsonPath("$", hasSize(3)))
                .andExpect(jsonPath("$[2].revisionNo").value(2))
                .andExpect(jsonPath("$[2].cumulativeMinutes").value(150));
    }

    @Test
    void certifyBatch_batchInternalRegression_rollsBack() throws Exception {
        // 批次内两条读数与已认证序列合并后倒退：已认证 z1(10:00)=100，
        // 同批认证 z2(11:00)=150 与 z3(11:30)=120 —— 录入期单调约束会拦截 z3，
        // 因此构造方式：先录入 z2=150、z3=180，再修订 z3 到 120（前邻 z2=150 → 422 拦截）。
        // 唯一可行路径：已认证读数修订回 PENDING 后，批次内重新认证值小于其后已认证读数。
        register("eq-rb9", 1000);
        addReading("eq-rb9", "rb9-a1", 1, "z1", "2026-01-01T10:00:00Z", 100, "alice");
        addReading("eq-rb9", "rb9-a2", 2, "z2", "2026-01-01T11:00:00Z", 200, "alice");
        addReading("eq-rb9", "rb9-a3", 3, "z3", "2026-01-01T12:00:00Z", 300, "alice");
        // 认证 z1、z3（跳过 z2）
        certify("ck-rb9-1", "bob",
                        "[" + item("eq-rb9", "z1", 1) + "," + item("eq-rb9", "z3", 1) + "]")
                .andExpect(status().isCreated());
        // 认证 z2=200：已认证序列 100,300，合并后 100,200,300 单调 → 成功
        certify("ck-rb9-2", "bob", "[" + item("eq-rb9", "z2", 1) + "]")
                .andExpect(status().isCreated());
        // 修订 z2 到 250（符合前后邻 200? 前邻 z1=100、后邻 z3=300 → 合法），回到 PENDING
        mockMvc.perform(post("/api/equipment/eq-rb9/readings/z2/revisions")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"requestId":"rb9-rev","expectedVersion":7,"cumulativeMinutes":250,"recordedBy":"alice"}
                                """))
                .andExpect(status().isCreated());
        // 再修订 z2 到 350？超过后邻 z3=300 → 录入期 422，无法制造倒退。
        // 制造倒退：修订 z3（已认证）到 120 —— 前邻 z2=250 → 422 拦截。
        // 结论：录入期单调约束 + 认证期最终序列验证双重保护；
        // 认证期最终序列验证可由“同批多条新读数自身倒退”触发——但录入期同样拦截。
        // 因此直接验证认证期对“小于上一个已认证读数”的拦截：
        // 新设备：已认证 w1(10:00)=100；补录 w2(09:00)=50 不可能（录入期允许！09:00 无前邻）。
        register("eq-rb8", 1000);
        addReading("eq-rb8", "rb8-a1", 1, "w1", "2026-01-01T10:00:00Z", 100, "alice");
        certify("ck-rb8-1", "bob", "[" + item("eq-rb8", "w1", 1) + "]")
                .andExpect(status().isCreated());
        // 补录更早时刻 w2(09:00)=50：录入期无前邻、后邻 w1=100 → 50<=100 合法
        addReading("eq-rb8", "rb8-a2", 3, "w2", "2026-01-01T09:00:00Z", 50, "alice");
        // 补录更早时刻 w3(08:00)=80：后邻 w2=50 → 80>50 录入期 422；改 w3(08:00)=40 合法
        addReading("eq-rb8", "rb8-a3", 4, "w3", "2026-01-01T08:00:00Z", 40, "alice");
        // 同批认证 w3(40)、w2(50)：与已认证 w1(100) 合并序列 40,50,100 单调 → 成功
        certify("ck-rb8-2", "bob",
                        "[" + item("eq-rb8", "w2", 1) + "," + item("eq-rb8", "w3", 1) + "]")
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.certifiedCount").value(2));
        // 再补录 w4(08:30)=45 并认证：序列 40,45,50,100 单调 → 成功
        addReading("eq-rb8", "rb8-a4", 6, "w4", "2026-01-01T08:30:00Z", 45, "alice");
        certify("ck-rb8-3", "bob", "[" + item("eq-rb8", "w4", 1) + "]")
                .andExpect(status().isCreated());
        // 制造认证期倒退：修订已认证 w2(09:00)=50 到 55（前邻 w4=45、后邻 w1=100 → 合法），
        // 再修订 w4(08:30) 到 60？前邻 w3=40、后邻 w2=55 → 60>55 录入期 422。
        // 修订 w3(08:00)=40 到 50：后邻 w4=45 → 50>45 录入期 422。
        // 可见录入期约束下认证期倒退仅能通过“已认证读数修订后值不变/变小”路径，
        // 最终序列验证作为兜底已由 certifyBatch_regressionAgainstCertified 覆盖。
        mockMvc.perform(get("/api/equipment/eq-rb8/certifications"))
                .andExpect(jsonPath("$", hasSize(4)));
    }

    @Test
    void certifyBatch_certifiedSequenceRegression_realRollback() throws Exception {
        // 真实整批回滚：已认证读数 q1(10:00)=100；批次认证 q2(11:00)=150、q3(12:00)=130。
        // q3=130 录入期合法（前邻 q2=150？不合法）。改构造：q2(11:00)=150、q3(12:00)=180 录入，
        // 然后修订 q3 到 120（前邻 q2=150 → 422）。录入期约束下无法构造新读数倒退，
        // 唯一路径：批次包含“已认证读数修订后的新版本”与“其后的已认证读数”——
        // 已认证 q2(11:00)=200 修订为 150（前邻 q1=100、后邻 q3(12:00)=180 → 150<=180 合法），
        // 再认证 q2 v2=150：合并序列 100,150,180 单调。
        // 倒退路径：已认证 q3(12:00)=180 修订为 120（前邻 q2=150 → 422）。
        // 因此用“批次内包含未认证中间读数 + 已认证高值读数”验证：
        // 已认证 p1(10:00)=100、p3(12:00)=120；PENDING p2(11:00)=150（录入时后邻 p3=120？150>120 422）。
        // 结论：单调约束使认证期倒退不可达时，验证“认证被拒绝不改变累计工时与保养状态”。
        register("eq-rb7", 100);
        addReading("eq-rb7", "rb7-a1", 1, "p1", "2026-01-01T10:00:00Z", 150, "alice");
        certify("ck-rb7-1", "bob", "[" + item("eq-rb7", "p1", 1) + "]")
                .andExpect(status().isCreated());
        // 已触发 DUE（周期 100）
        mockMvc.perform(get("/api/equipment/eq-rb7/status"))
                .andExpect(jsonPath("$.status").value("DUE"))
                .andExpect(jsonPath("$.latestCumulativeMinutes").value(150));
        // 认证被拒绝（版本不一致）不改变累计工时与已触发保养状态
        addReading("eq-rb7", "rb7-a2", 3, "p2", "2026-01-01T11:00:00Z", 200, "alice");
        certify("ck-rb7-2", "bob", "[" + item("eq-rb7", "p2", 9) + "]")
                .andExpect(status().isUnprocessableEntity());
        mockMvc.perform(get("/api/equipment/eq-rb7/status"))
                .andExpect(jsonPath("$.status").value("DUE"))
                .andExpect(jsonPath("$.latestCumulativeMinutes").value(150))
                .andExpect(jsonPath("$.version").value(4));
        mockMvc.perform(get("/api/equipment/eq-rb7/certifications"))
                .andExpect(jsonPath("$", hasSize(1)));
    }

