    mockMvc.perform(get("/api/equipment/eq-mono/readings"))
            .andExpect(jsonPath("$", hasSize(5)));
    mockMvc.perform(get("/api/equipment/eq-mono/certifications"))
            .andExpect(jsonPath("$", hasSize(5)));
}

