                .andExpect(jsonPath("$[0].batchSeq").value(1))
                .andExpect(jsonPath("$[1].batchSeq").value(2));
        mockMvc.perform(get("/api/equipment/eq-b2/certifications"))
                .andExpect(jsonPath("$", hasSize(1)))
                .andExpect(jsonPath("$[0].batchSeq").value(3));
