            // 认证先提交：认证成功；退役因设备版本已前进（期望 2，当前 3）→ 409
            assertEquals(201, certifyStatus);
            assertEquals(409, retireStatus, "认证先提交使版本前进，退役应版本冲突");
            mockMvc.perform(get("/api/equipment/eq-ct/readings"))
